import { createContext, type PropsWithChildren } from 'react';

import { isZoomTransitionEnabled } from './ZoomTransitionEnabler.ios';
import {
  getInternalExpoRouterParams,
  INTERNAL_EXPO_ROUTER_ZOOM_TRANSITION_SCREEN_ID_PARAM_NAME,
  INTERNAL_EXPO_ROUTER_ZOOM_TRANSITION_SOURCE_ID_PARAM_NAME,
} from '../navigationParams';
import { useIsPreview } from './preview/PreviewRouteContext';
import type { LinkProps } from './useLinkHooks';

export const ZoomContext = createContext<{ identifier: string | null }>({ identifier: null });
export const ZoomSourceContext = createContext<
  | {
      identifier: string;
      alignment: LinkProps['unstable_transitionAlignmentRect'];
    }
  | undefined
>(undefined);

export function ZoomContextProvider({ route, children }: PropsWithChildren<{ route: unknown }>) {
  const isPreview = useIsPreview();
  if (
    isZoomTransitionEnabled() &&
    !isPreview &&
    route &&
    typeof route === 'object' &&
    'params' in route &&
    typeof route.params === 'object' &&
    'key' in route &&
    typeof route.key === 'string'
  ) {
    const params = route.params ?? {};
    const internalParams = getInternalExpoRouterParams(params);
    const zoomTransitionId =
      internalParams[INTERNAL_EXPO_ROUTER_ZOOM_TRANSITION_SOURCE_ID_PARAM_NAME];
    const zoomTransitionScreenId =
      internalParams[INTERNAL_EXPO_ROUTER_ZOOM_TRANSITION_SCREEN_ID_PARAM_NAME];
    const hasZoomTransition = !!zoomTransitionId && zoomTransitionScreenId === route.key;
    if (hasZoomTransition && typeof zoomTransitionId === 'string') {
      return <ZoomContext value={{ identifier: zoomTransitionId }}>{children}</ZoomContext>;
    }
  }
  return children;
}
